    assert_eq!(still["content"], "fond");

    let (status, body, _) = call(&app, "DELETE", &format!("{pages}?path=/Atelier/ligne/bas&api-version=7.1"), Some(&auth), None, "application/json", None).await;
    assert_eq!(status, StatusCode::OK, "{body}");
