    assert_eq!(pompe["values"][0]["value"], "atelier");
    assert!(pompe["url"].as_str().unwrap().contains("/_apis/test/configurations/"));
    let (status, body, _) = call(
        &app,
        "POST",
        configs,
        Some(&auth),
        None,
        "application/json",
        Some(r#"{"name":"ada","isDefault":true}"#),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert!(body.contains("configuration par défaut"), "{body}");
    let (status, body, _) = call(
        &app,
        "POST",
        configs,
        Some(&auth),
        None,
        "application/json",
        Some(r#"{"name":"ada","values":[{"name":"Valeur","value":"Linux"}]}"#),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let ada: serde_json::Value = serde_json::from_str(&body).unwrap();
