    assert_eq!(status, StatusCode::OK, "{body}");
    shelve(&app, &auth, "AzurzDemo", &pompe, "Pompe").await;

    let (status, body, _) = call(&app, "DELETE", &restore, Some(&auth), None, "application/json", None).await;
