        assert_eq!(created["status"], "enabled");
        assert_eq!(created["filter"]["eventType"], "ms.vss-work.workitem-changed-event");
        assert_eq!(created["scope"]["id"], project);
        assert_eq!(created["subscriber"]["id"], "azurz");
