    assert_eq!(sibling["projectEntitlements"][0]["projectRef"]["id"], "AzurzDemo");
    let other = kept["value"].as_array().unwrap().iter().find(|item| item["user"]["displayName"] == "Atelier").unwrap();
    assert_eq!(other["id"], atelier);
