    let (status, body, _) = call(&app, "GET", list, Some(&auth), None, "application/json", None).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let kept: serde_json::Value = serde_json::from_str(&body).unwrap();
    assert_eq!(kept["count"], 1, "{body}");
