    assert_eq!(relais["color"], "CC293D");
    assert_eq!(relais["rank"], 8);
    assert_eq!(relais["description"], "Voisin");
    assert_eq!(relais["inherits"]["behaviorRefName"], "System.PortfolioBehavior");
