    let one = format!("/azurz/AzurzDemo/_apis/testplan/sharedparameters/{}?api-version=7.1", pompe["id"].as_str().unwrap());
    let (status, body, _) = call(&app, "DELETE", &one, Some(&auth), None, "application/json", None).await;
